#!/bin/bash
# Run everything.
#
#   scripts/check.sh [--clean]
#
# --clean rebuilds the Swift package from scratch.
#
# The Swift lane holds the depth pass to an exact ray cast, the contours to
# the function they were placed by, the surfaces to their analytic
# visibility, and the special functions, the marching squares and the npy
# reader to the oracle fixtures numpy, scipy, mpmath and contourpy wrote
# (tests/oracles.py, regenerated by hand; nothing here runs Python). The
# golden fixtures are the other kind: kurven's own answers, which
# `kurven-cli fixtures` must reproduce byte for byte, so a change to one is
# made on purpose and committed with its diff.
#
# Why --clean exists, and why this script forces a relink by default: SwiftPM's
# incremental build does not reliably rebuild or relink a target when a type's
# layout or a function's signature changes in a library it depends on. The
# symptom is not a compile error -- it is a segfault in unrelated code, or a
# missing symbol at link time. It has happened four times in this repository's
# short Swift history, so the cheap defence is on by default.

set -uo pipefail

ROOT="$(cd "$(dirname "$0")/.." && pwd)"
PACKAGE="$ROOT"

CLEAN=0
for arg in "$@"; do
    case "$arg" in
        --clean) CLEAN=1 ;;
        *) echo "usage: $0 [--clean]" >&2; exit 2 ;;
    esac
done

failures=0
step() {
    local name="$1"; shift
    printf '\n\033[1m== %s\033[0m\n' "$name"
    if "$@"; then
        return 0
    fi
    printf '\033[31m   FAILED: %s\033[0m\n' "$name"
    failures=$((failures + 1))
}

if [ "$CLEAN" = 1 ]; then
    rm -rf "$PACKAGE/.build"
else
    # Force the executables to relink against whatever the libraries now are.
    touch "$PACKAGE"/Sources/kurven-test/*.swift \
          "$PACKAGE"/Sources/kurven-cli/*.swift \
          "$PACKAGE"/Sources/KurvenApp/*.swift 2>/dev/null
fi

# Warnings fail the build here, so a stray one is caught by this lane and by
# CI instead of scrolling past in a terminal. A plain `swift build` still
# tolerates them, which is the right default while iterating.
step "swift build (release)" swift build -c release --package-path "$PACKAGE" \
    -Xswiftc -warnings-as-errors
BIN="$PACKAGE/.build/release"

step "swift lane" "$BIN/kurven-test"
step "schema round trip" "$BIN/kurven-cli" contract "$ROOT/tests/fixtures/contract"

# A polyhedron's hatching in four widths bakes to a stroke layer per width,
# each dumped and listed by its name and the outline by its own; and a
# resolution no depth buffer has is refused, saved or baked.
cli() {
    local dir="$PACKAGE/.build/cli-check" ico="$ROOT/tests/fixtures/contract/polyhedron_icosahedron.kurven"
    rm -rf "$dir" && mkdir -p "$dir" || return 1
    "$BIN/kurven-cli" bake "$ico" --outline 0.5 --dump "$dir/ico" -o "$dir/ico.svg" > "$dir/ico.txt" || return 1
    for name in edges "hatching 1of4" "hatching 2of4" "hatching 3of4" "hatching 4of4" outline; do
        [ -f "$dir/ico.$name.npy" ] && [ -f "$dir/ico.$name.idx.npy" ] || { echo "no dump of $name"; return 1; }
    done
    grep -q 'hatching 4/4 .* paths' "$dir/ico.txt" && grep -q 'outline .* from the depth buffer' "$dir/ico.txt" &&
    [ "$(grep -c 'from the depth buffer' "$dir/ico.txt")" = 1 ] &&
    grep -q '"layers":\["edges","hatching 1/4","hatching 2/4","hatching 3/4","hatching 4/4","outline"\]' \
        "$dir/ico.frame.json" &&
    ! "$BIN/kurven-cli" surface solid --kind cube --resolution 0 --save "$dir/zero.kurven" 2>/dev/null &&
    ! "$BIN/kurven-cli" bake "$ico" --resolution 20001 -o "$dir/huge.svg" 2>/dev/null &&
    [ ! -e "$dir/zero.kurven" ] && [ ! -e "$dir/huge.svg" ]
}
step "the CLI bakes a polyhedron's widths as layers of their own, and refuses a resolution no buffer has" cli

# Written in place and compared with the commit, so the check needs no
# scratch tree and a failure leaves the difference in the working copy to be
# read with `git diff`. Untracked files count: a set that grew a file is a
# set that changed.
golden() {
    "$BIN/kurven-cli" fixtures "$ROOT/tests/fixtures" >/dev/null || return 1
    git -C "$ROOT" add --intent-to-add tests/fixtures
    git -C "$ROOT" diff --exit-code --stat -- tests/fixtures
}
step "the committed golden fixtures are what kurven-cli fixtures writes" golden

# The app's own document, driven without a window (a bundle named by a bare
# path opens none): a surface saved by the CLI, opened, saved as ⌘S saves it,
# reopened and baked, is the CLI's bundle and drawing byte for byte. Then a
# level slider's count, set before an edit of the request, stays on its
# family through the edit and is saved, and the app's bake of the result is
# the CLI's bake of the same bundle; and the contract's restyled surface,
# edited, keeps its levels and the contours its request does not draw. A
# polyhedron likewise: the frame with Turing's hatching, saved by the CLI,
# saved again by the app, reopened and baked, is `surface solid`'s drawing
# byte for byte; and 40 strokes set as the hatching's slider sets them
# (5.657 / 40 apart across the largest face) save and bake as `surface solid
# --spacing` at that spacing saves and bakes, bundle and drawing.
app() {
    local dir="$PACKAGE/.build/app-check"
    rm -rf "$dir" && mkdir -p "$dir" || return 1
    "$BIN/kurven-cli" surface sn --save "$dir/a.kurven" >/dev/null &&
    "$BIN/kurven-cli" surface sn -o "$dir/a.svg" >/dev/null &&
    "$BIN/KurvenApp" "$dir/a.kurven" --save "$dir/b.kurven" >/dev/null &&
    "$BIN/KurvenApp" "$dir/b.kurven" --bake "$dir/b.svg" >/dev/null &&
    cmp "$dir/a.kurven/manifest.json" "$dir/b.kurven/manifest.json" &&
    cmp "$dir/a.svg" "$dir/b.svg" &&
    "$BIN/KurvenApp" "$dir/b.kurven" --levels ang_major=4 --set major=2.5 --save "$dir/c.kurven" >/dev/null &&
    "$BIN/KurvenApp" "$dir/c.kurven" --bake "$dir/c.svg" >/dev/null &&
    "$BIN/kurven-cli" bake "$dir/c.kurven" -o "$dir/c-cli.svg" >/dev/null &&
    cmp "$dir/c.svg" "$dir/c-cli.svg" &&
    "$BIN/kurven-cli" inspect "$dir/c.kurven" > "$dir/c.txt" &&
    grep -q 'ang_major .* 4 levels of phase' "$dir/c.txt" &&
    grep -q 'mag_minor .* 24 levels of magnitude' "$dir/c.txt" &&
    grep -q '"major":2.5' "$dir/c.kurven/manifest.json" &&
    "$BIN/KurvenApp" "$ROOT/tests/fixtures/contract/surface.kurven" --levels ang_major=4 --set major=2.5 \
        --save "$dir/d.kurven" >/dev/null &&
    "$BIN/kurven-cli" inspect "$dir/d.kurven" > "$dir/d.txt" &&
    grep -q 'ang_major .* 4 levels of phase' "$dir/d.txt" &&
    grep -q 'mag_major .* 3 levels of magnitude' "$dir/d.txt" &&
    grep -q '2 levels of v on' "$dir/d.txt" && grep -q '3 levels of height on' "$dir/d.txt" &&
    "$BIN/kurven-cli" surface solid --kind frame --hatching turing --save "$dir/p.kurven" >/dev/null &&
    "$BIN/kurven-cli" surface solid --kind frame --hatching turing -o "$dir/p.svg" >/dev/null &&
    "$BIN/KurvenApp" "$dir/p.kurven" --save "$dir/q.kurven" >/dev/null &&
    "$BIN/KurvenApp" "$dir/q.kurven" --bake "$dir/q.svg" >/dev/null &&
    cmp "$dir/p.kurven/manifest.json" "$dir/q.kurven/manifest.json" &&
    cmp "$dir/p.svg" "$dir/q.svg" &&
    "$BIN/KurvenApp" "$dir/q.kurven" --strokes hatching=40 --save "$dir/r.kurven" >/dev/null &&
    "$BIN/KurvenApp" "$dir/r.kurven" --bake "$dir/r.svg" >/dev/null &&
    "$BIN/kurven-cli" surface solid --kind frame --hatching turing --spacing 0.1414213562373095 \
        --save "$dir/s.kurven" -o "$dir/s.svg" >/dev/null &&
    cmp "$dir/r.kurven/manifest.json" "$dir/s.kurven/manifest.json" &&
    cmp "$dir/r.svg" "$dir/s.svg"
}
step "the app saves, restyles and bakes a surface and a polyhedron as the CLI does, with no window" app

# Picking, with no window: a click at a pixel reads the depth the frame left
# there, takes it back through the camera, and names the face under it. The
# frame's top face, holes and all, and a wall of its hole; the torus, and its
# hole, where there is nothing; the second tile of a tiled landscape; a
# plateau and two walls. A click off the drawing clears the pick: the frame
# drawn after one is the frame drawn with no pick, and a pick changes it.
pick() {
    local dir="$PACKAGE/.build/pick-check" c="$ROOT/tests/fixtures/contract" out
    rm -rf "$dir" && mkdir -p "$dir" || return 1
    out=$("$BIN/KurvenApp" "$c/polyhedron_frame.kurven" --pick 300,250 --pick 760,300 --pick 600,400) || return 1
    printf '%s\n' "$out"
    [ "$(printf '%s\n' "$out" | sed -n 1p | cut -d' ' -f2-4)" = "picked face 0" ] &&
    [ "$(printf '%s\n' "$out" | sed -n 2p | cut -d' ' -f2-4)" = "picked face 7" ] &&
    [ "$(printf '%s\n' "$out" | sed -n 3p)" = "Kurven: picked nothing" ] || return 1
    out=$("$BIN/KurvenApp" "$c/surface_torus.kurven" --pick 300,600 --pick 600,400) || return 1
    printf '%s\n' "$out"
    [ "$(printf '%s\n' "$out" | sed -n 1p | cut -d' ' -f2-3)" = "picked surface" ] &&
    [ "$(printf '%s\n' "$out" | sed -n 2p)" = "Kurven: picked nothing" ] || return 1
    out=$("$BIN/KurvenApp" "$c/uniform_mesh.kurven" --pick 900,200 --pick 300,200) || return 1
    printf '%s\n' "$out"
    [ "$(printf '%s\n' "$out" | sed -n 1p | cut -d' ' -f2-6)" = "picked graph on tile 1" ] &&
    [ "$(printf '%s\n' "$out" | sed -n 2p | cut -d' ' -f2-4)" = "picked graph at" ] || return 1
    out=$("$BIN/KurvenApp" "$c/landscape.kurven" --pick 900,100 --pick 1100,200 --pick 300,700) || return 1
    printf '%s\n' "$out"
    [ "$(printf '%s\n' "$out" | sed -n 1p | cut -d' ' -f2-4)" = "picked plateau 0" ] &&
    [ "$(printf '%s\n' "$out" | sed -n 2p | cut -d' ' -f2-4)" = "picked wall 1" ] &&
    [ "$(printf '%s\n' "$out" | sed -n 3p | cut -d' ' -f2-4)" = "picked wall 0" ] || return 1
    "$BIN/KurvenApp" "$c/polyhedron_frame.kurven" --screenshot "$dir/none.png" >/dev/null &&
    "$BIN/KurvenApp" "$c/polyhedron_frame.kurven" --pick 300,250 --screenshot "$dir/picked.png" >/dev/null &&
    "$BIN/KurvenApp" "$c/polyhedron_frame.kurven" --pick 300,250 --pick 600,400 --screenshot "$dir/cleared.png" >/dev/null &&
    cmp "$dir/none.png" "$dir/cleared.png" && ! cmp -s "$dir/none.png" "$dir/picked.png"
}
step "the app picks a face at a pixel, on a polyhedron, a torus and a tiled landscape, and a click off the drawing clears it, with no window" pick

# The vocabulary: a word docs/glossary.md retired, back in the code or the
# docs, in a file's text or its name. The hits are printed; the fix is the
# glossary's word for the thing, or a new glossary entry if the old word
# turns out to be right after all. A word is matched on its own or as one
# component of a camelCase or snake_case name: it begins after anything but
# a letter, or at a capital after a lower-case letter or a digit, and ends
# before anything but a lower-case letter.
retired() {
    local words pattern hits names status
    local where=(Sources README.md docs ':(exclude)docs/glossary.md' ':(exclude)docs/notes')
    words=$(grep -v -e '^#' -e '^$' "$ROOT/scripts/retired-words.txt" | sed 's/.*/(?:&)/' | paste -sd '|' -)
    pattern="(?:(?<![A-Za-z])|(?<=[a-z0-9])(?=[A-Z]))(?:$words)(?![a-z])"
    hits=$(git -C "$ROOT" grep --untracked -n -P -e "$pattern" -- "${where[@]}")
    status=$?
    # 1 is no match; more is git grep failing, on a pattern it cannot
    # compile for one, which must not read as a clean tree.
    if [ "$status" -gt 1 ]; then
        echo "git grep failed with status $status"
        return 1
    fi
    names=$(git -C "$ROOT" ls-files --cached --others --exclude-standard -- "${where[@]}" \
        | PATTERN="$pattern" perl -ne 'print if /$ENV{PATTERN}/') || return 1
    [ -z "$hits" ] && [ -z "$names" ] && return 0
    [ -n "$hits" ] && printf '%s\n' "$hits"
    [ -n "$names" ] && printf '%s\n' "$names"
    return 1
}
step "no retired word is back (docs/glossary.md)" retired

printf '\n'
if [ "$failures" = 0 ]; then
    printf '\033[32mall green\033[0m\n'
    exit 0
fi
printf '\033[31m%d step(s) failed\033[0m\n' "$failures"
exit 1
